var datos = msg.payload;

if (datos.hasOwnProperty('estado_luz')) {
    var estado = parseInt(datos.estado_luz);
    var ahora = new Date().getTime();
    var opciones = { timeZone: 'America/Bogota', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false };

    // 1. Si la luz se enciende, guardamos la hora en la memoria de Node-RED
    if (estado === 1) {
        context.set('tEncendido', ahora);
        return null; 
    }

    // 2. Si la luz se apaga, calculamos y preparamos el mensaje
    if (estado === 0) {
        var tEncendido = context.get('tEncendido');
        var tApagado = ahora;

        if (!tEncendido) {
            tEncendido = tApagado - 5000; // Respaldo de 5 segundos si no encuentra el inicio
        }

        var horaIn = new Date(tEncendido).toLocaleTimeString('es-CO', opciones);
        var horaOut = new Date(tApagado).toLocaleTimeString('es-CO', opciones);

        // --- CONFIGURACIÓN REAL BASADA EN TUS DATOS DE EPM Y LÁMPARA ---
        var POTENCIA_BOMBILLO = 18;  // Plafón LED de sobreponer de 18 Watts
        var PRECIO_KWH = 447.69;     // Tarifa oficial Estrato 2 de tu tabla de EPM ($/kWh)

        // --- CÁLCULO MATEMÁTICO REAL ---
        var segundosTotales = (tApagado - tEncendido) / 1000;
        var horasTotales = segundosTotales / 3600;

        // Fórmula oficial: (Watts * Horas) / 1000
        var consumoKWh = (POTENCIA_BOMBILLO * horasTotales) / 1000; 

        // Cálculo del costo en pesos colombianos
        var costoPesos = consumoKWh * PRECIO_KWH;

        // --- LÓGICA DE TIEMPO NATURAL EN ESPAÑOL ---
        var textoTiempo = "";

        if (segundosTotales >= 3600) {
            var horasEnteras = Math.floor(segundosTotales / 3600);
            var minutosRestantes = Math.floor((segundosTotales % 3600) / 60);
            textoTiempo = horasEnteras + " horas con " + minutosRestantes + " minutos";
        } else if (segundosTotales >= 60) {
            var minutosEnteros = Math.floor(segundosTotales / 60);
            var segundosRestantes = Math.floor(segundosTotales % 60);
            textoTiempo = minutosEnteros + " minutos con " + segundosRestantes + " segundos";
        } else {
            textoTiempo = segundosTotales.toFixed(1) + " segundos";
        }

        // --- TEXTO FINAL CON DATOS VERIFICABLES ---
        var textoLimpio = "Reporte de Iluminacion\n\n" +
                          "Hora de encendido: " + horaIn + "\n" +
                          "Hora de apagado: " + horaOut + "\n" +
                          "Tiempo total: " + textoTiempo + "\n" +
                          "Consumo estimado: " + consumoKWh.toFixed(6) + " kWh\n" +
                          "Costo del consumo Estrato 2: $" + costoPesos.toFixed(4) + " COP";

        msg.payload = {
            chatId: "8253243188",
            type: "message",
            content: textoLimpio
        };

        return msg; 
    }
}
return null;
